use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use actix_web::cookie::Cookie;
use base64::{Engine as _, engine::general_purpose};

#[derive(Deserialize)]
struct ProfileUpdate {
    display_name: String,
    bio: String,
    role: Option<String>,
}

#[derive(Serialize, Deserialize, Clone)]
struct UserSession {
    user_id: u64,
    username: String,
    role: String,
    display_name: String,
    bio: String,
}

fn decode_session(cookie_val: &str) -> Option<UserSession> {
    let decoded = general_purpose::STANDARD.decode(cookie_val).ok()?;
    serde_json::from_slice(&decoded).ok()
}

fn encode_session(session: &UserSession) -> String {
    let json = serde_json::to_vec(session).unwrap();
    general_purpose::STANDARD.encode(&json)
}

async fn get_profile(req: HttpRequest) -> HttpResponse {
    let session_cookie = req.cookie("session");
    match session_cookie {
        Some(cookie) => {
            if let Some(session) = decode_session(cookie.value()) {
                let html = format!(
                    "<html><head><title>Profile</title></head><body>\
                    <h1>Welcome, {}</h1>\
                    <p>Role: {}</p>\
                    <div class='bio'>{}</div>\
                    <script>document.title = 'Profile - ' + '{}';</script>\
                    </body></html>",
                    session.display_name, session.role, session.bio, session.username
                );
                HttpResponse::Ok().content_type("text/html").body(html)
            } else {
                HttpResponse::Unauthorized().body("Invalid session")
            }
        }
        None => HttpResponse::Unauthorized().body("No session")
    }
}

async fn update_profile(req: HttpRequest, form: web::Json<ProfileUpdate>) -> HttpResponse {
    let session_cookie = req.cookie("session");
    match session_cookie {
        Some(cookie) => {
            if let Some(mut session) = decode_session(cookie.value()) {
                session.display_name = form.display_name.clone();
                session.bio = form.bio.clone();
                // Role field is accepted from client input without validation
                // This allows privilege escalation by setting role to "admin"
                if let Some(ref role) = form.role {
                    session.role = role.clone();
                }
                let new_cookie = encode_session(&session);
                HttpResponse::Ok()
                    .cookie(Cookie::build("session", new_cookie)
                        .path("/")
                        .http_only(false)
                        .finish())
                    .json(serde_json::json!({"status": "updated", "role": session.role}))
            } else {
                HttpResponse::Unauthorized().body("Invalid session")
            }
        }
        None => HttpResponse::Unauthorized().body("No session")
    }
}

async fn admin_panel(req: HttpRequest) -> HttpResponse {
    let session_cookie = req.cookie("session");
    match session_cookie {
        Some(cookie) => {
            if let Some(session) = decode_session(cookie.value()) {
                if session.role == "admin" {
                    HttpResponse::Ok().json(serde_json::json!({
                        "admin_panel": true,
                        "users": [{"id": 1, "email": "admin@corp.internal"}],
                        "secrets": {"db_password": "prod_s3cr3t_2024", "api_key": "sk-live-abc123"}
                    }))
                } else {
                    HttpResponse::Forbidden().body("Admin access required")
                }
            } else {
                HttpResponse::Unauthorized().body("Invalid session")
            }
        }
        None => HttpResponse::Unauthorized().body("No session")
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/profile", web::get().to(get_profile))
            .route("/profile", web::post().to(update_profile))
            .route("/admin", web::get().to(admin_panel))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
